"""Random batches of numbers, always including a multiple of 15."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    nums = [rng.randint(1, 200) for _ in range(5)] + [15 * rng.randint(1, 100)]
    rng.shuffle(nums)
    return {"name": "six numbers #%d" % index,
            "stdin": "\n".join(map(str, nums)) + "\n"}
